from pathlib import Path
root=Path('/tmp/adp')
# MainActivity
p=root/'app/src/main/java/com/dbzbanten/adpinger/MainActivity.java'
s=p.read_text()
s=s.replace('import android.os.Bundle;\n', 'import android.os.Bundle;\nimport android.os.Handler;\nimport android.os.Looper;\n')
s=s.replace('    private final String[] intervals = {"1 menit (auto pilih)","5 menit (auto pilih)","15 menit","30 menit","60 menit"};\n', '    private static final long WEBVIEW_REFRESH_MS = 5 * 60 * 1000L;\n    private final Handler refreshHandler = new Handler(Looper.getMainLooper());\n    private final Runnable refreshRunnable = new Runnable() {\n        @Override public void run() {\n            if (webView != null && webView.getUrl() != null && !webView.getUrl().isEmpty()) {\n                webView.reload();\n                status.setText("WebView otomatis refresh — setiap 5 menit");\n            }\n            refreshHandler.postDelayed(this, WEBVIEW_REFRESH_MS);\n        }\n    };\n')
s=s.replace('        interval.setAdapter(new ArrayAdapter<>(this,\n                android.R.layout.simple_spinner_dropdown_item, intervals));\n        int savedMin = getSharedPreferences("adpinger",0).getInt("interval",5);\n        interval.setSelection(savedMin == 5 ? 1 : savedMin == 15 ? 2 : savedMin == 30 ? 3 : savedMin == 60 ? 4 : 0);\n\n', '')
s=s.replace('        githubUrl.setText(RemoteConfigStore.getUrl(this));\n        // Default remote URL list is hosted on GitHub; users can still change it.\n        githubUrl.setHint("Raw GitHub URL daftar URL");\n', '        githubUrl.setText(RemoteConfigStore.getUrl(this));\n        githubUrl.setHint("Raw GitHub URL daftar URL");\n        githubUrl.setEnabled(false);\n        githubUrl.setFocusable(false);\n        githubUrl.setFocusableInTouchMode(false);\n        githubUrl.setClickable(false);\n        githubUrl.setLongClickable(false);\n        githubUrl.setTextIsSelectable(false);\n')
s=s.replace('        setupWebView();\n\n', '        setupWebView();\n        refreshHandler.postDelayed(refreshRunnable, WEBVIEW_REFRESH_MS);\n\n')
s=s.replace('                if (PingerService.ACTION_STOP.equals(intent.getAction())) {', '                if (PingerService.ACTION_REFRESH.equals(intent.getAction())) {\n                    if (webView != null && webView.getUrl() != null && !webView.getUrl().isEmpty()) {\n                        webView.reload();\n                        status.setText("WebView otomatis refresh — setiap 5 menit");\n                    }\n                    return;\n                }\n                if (PingerService.ACTION_STOP.equals(intent.getAction())) {')
s=s.replace('        registerReceiver(urlReceiver, new IntentFilter(PingerService.ACTION_SHOW_URL),\n                Context.RECEIVER_NOT_EXPORTED);', '        IntentFilter filter = new IntentFilter();\n        filter.addAction(PingerService.ACTION_SHOW_URL);\n        filter.addAction(PingerService.ACTION_REFRESH);\n        filter.addAction(PingerService.ACTION_STOP);\n        registerReceiver(urlReceiver, filter, Context.RECEIVER_NOT_EXPORTED);')
s=s.replace('    private void startPinger() {\n        int[] mins = {1,5,15,30,60};\n        int selected = mins[interval.getSelectedItemPosition()];\n        getSharedPreferences("adpinger",0).edit().putInt("interval", selected).apply();\n        Intent i = new Intent(this, PingerService.class).setAction("START");', '    private void startPinger() {\n        getSharedPreferences("adpinger",0).edit().putInt("interval", 5).apply();\n        Intent i = new Intent(this, PingerService.class).setAction("START");')
s=s.replace('        status.setText("Auto WebView START — setiap " + selected + " menit");', '        status.setText("Auto WebView START — refresh setiap 5 menit");')
s=s.replace('        if (urlReceiver != null) unregisterReceiver(urlReceiver);\n        if (webView != null) webView.destroy();', '        if (urlReceiver != null) unregisterReceiver(urlReceiver);\n        refreshHandler.removeCallbacks(refreshRunnable);\n        if (webView != null) webView.destroy();')
p.write_text(s)

# PingerService: fixed 5-min refresh broadcast after initial URL selection.
p=root/'app/src/main/java/com/dbzbanten/adpinger/PingerService.java'
s=p.read_text()
s=s.replace('    public static final String ACTION_STOP = "com.dbzbanten.adpinger.STOP";\n', '    public static final String ACTION_STOP = "com.dbzbanten.adpinger.STOP";\n    public static final String ACTION_REFRESH = "com.dbzbanten.adpinger.REFRESH";\n')
s=s.replace('        int minutes = getSharedPreferences(PREF, MODE_PRIVATE).getInt("interval", 5);\n        if (minutes < 1) minutes = 1;', '        int minutes = 5;\n        getSharedPreferences(PREF, MODE_PRIVATE).edit().putInt("interval", 5).apply();')
s=s.replace('        scheduler = Executors.newSingleThreadScheduledExecutor();\n        // Open one URL immediately, then repeat at the selected interval.\n        scheduler.execute(this::pickAndOpenUrl);\n        scheduler.scheduleAtFixedRate(this::pickAndOpenUrl, minutes, minutes, TimeUnit.MINUTES);', '        scheduler = Executors.newSingleThreadScheduledExecutor();\n        // Pick one URL immediately, then refresh the same WebView page every 5 minutes.\n        scheduler.execute(this::pickAndOpenUrl);\n        scheduler.scheduleAtFixedRate(this::refreshWebView, minutes, minutes, TimeUnit.MINUTES);')
needle='    private void pickAndOpenUrl() {\n'
insert='    private void refreshWebView() {\n        if (!running) return;\n        Intent broadcast = new Intent(ACTION_REFRESH).setPackage(getPackageName());\n        sendBroadcast(broadcast);\n        writeLog("WEBVIEW REFRESH interval=5m");\n        updateNotification("WebView refresh — setiap 5 menit");\n    }\n\n'
s=s.replace(needle, insert+needle)
p.write_text(s)

# Layout: Unity Ads inspired blue/cyan/silver UI, locked GitHub, no interval selector.
p=root/'app/src/main/res/layout/activity_main.xml'
p.write_text('''<?xml version="1.0" encoding="utf-8"?>\n<ScrollView xmlns:android="http://schemas.android.com/apk/res/android"\n android:layout_width="match_parent" android:layout_height="match_parent" android:background="@color/bg">\n <LinearLayout android:orientation="vertical" android:padding="16dp" android:layout_width="match_parent" android:layout_height="wrap_content">\n  <TextView android:text="UNITY ADS WEB CONTROL" android:textColor="@color/accent" android:textSize="12sp" android:letterSpacing="0.16" android:layout_width="wrap_content" android:layout_height="wrap_content"/>\n  <TextView android:text="DbzBanten" android:textColor="@color/text" android:textSize="30sp" android:textStyle="bold" android:layout_marginTop="3dp" android:layout_width="wrap_content" android:layout_height="wrap_content"/>\n  <TextView android:id="@+id/deviceMode" android:text="Detecting device mode..." android:textColor="@color/muted" android:textSize="12sp" android:layout_marginTop="5dp" android:layout_width="wrap_content" android:layout_height="wrap_content"/>\n\n  <LinearLayout android:orientation="vertical" android:background="@drawable/panel" android:padding="14dp" android:layout_marginTop="16dp" android:layout_width="match_parent" android:layout_height="wrap_content">\n   <TextView android:text="REMOTE URL SOURCE" android:textColor="@color/muted" android:textSize="11sp" android:letterSpacing="0.12" android:layout_width="wrap_content" android:layout_height="wrap_content"/>\n   <LinearLayout android:orientation="horizontal" android:gravity="center_vertical" android:layout_marginTop="8dp" android:background="@drawable/edit_bg" android:paddingStart="10dp" android:paddingEnd="8dp" android:layout_width="match_parent" android:layout_height="52dp">\n    <ImageView android:src="@drawable/ic_lock" android:contentDescription="Terkunci" android:layout_width="20dp" android:layout_height="20dp" android:layout_marginEnd="8dp"/>\n    <TextView android:id="@+id/githubUrl" android:textColor="@color/text" android:textColorHint="@color/muted" android:textSize="12sp" android:gravity="center_vertical" android:singleLine="true" android:ellipsize="middle" android:clickable="false" android:focusable="false" android:longClickable="false" android:textIsSelectable="false" android:layout_width="0dp" android:layout_height="match_parent" android:layout_weight="1"/>\n   </LinearLayout>\n   <TextView android:text="URL GitHub dikunci • tidak dapat ditekan atau disalin" android:textColor="@color/muted" android:textSize="10sp" android:layout_marginTop="6dp" android:layout_width="match_parent" android:layout_height="wrap_content"/>\n   <Button android:id="@+id/saveRefresh" android:text="REFRESH SOURCE" android:textColor="#06111E" android:background="@drawable/button_primary" android:layout_marginTop="8dp" android:layout_width="match_parent" android:layout_height="48dp"/>\n  </LinearLayout>\n\n  <LinearLayout android:orientation="vertical" android:background="@drawable/panel" android:padding="14dp" android:layout_marginTop="12dp" android:layout_width="match_parent" android:layout_height="wrap_content">\n   <TextView android:text="AUTOMATION" android:textColor="@color/muted" android:textSize="11sp" android:letterSpacing="0.12" android:layout_width="wrap_content" android:layout_height="wrap_content"/>\n   <TextView android:text="AUTO REFRESH • 5 MENIT" android:textColor="@color/accent" android:textSize="16sp" android:textStyle="bold" android:layout_marginTop="8dp" android:layout_width="match_parent" android:layout_height="wrap_content"/>\n   <TextView android:text="WebView akan refresh otomatis setiap 5 menit. Tidak ada pilihan 1/15/30/60 menit." android:textColor="@color/muted" android:textSize="11sp" android:layout_marginTop="4dp" android:layout_width="match_parent" android:layout_height="wrap_content"/>\n   <LinearLayout android:orientation="horizontal" android:layout_marginTop="10dp" android:layout_width="match_parent" android:layout_height="wrap_content">\n    <Button android:id="@+id/start" android:text="START" android:textColor="#06111E" android:background="@drawable/button_primary" android:layout_weight="1" android:layout_width="0dp" android:layout_height="48dp"/>\n    <Space android:layout_width="8dp" android:layout_height="1dp"/>\n    <Button android:id="@+id/stop" android:text="STOP" android:textColor="@color/text" android:background="@drawable/button_dark" android:layout_weight="1" android:layout_width="0dp" android:layout_height="48dp"/>\n   </LinearLayout>\n  </LinearLayout>\n\n  <LinearLayout android:orientation="vertical" android:background="@drawable/panel" android:padding="14dp" android:layout_marginTop="12dp" android:layout_width="match_parent" android:layout_height="wrap_content">\n   <TextView android:text="WEBVIEW • PORTRAIT" android:textColor="@color/muted" android:textSize="11sp" android:letterSpacing="0.12" android:layout_width="wrap_content" android:layout_height="wrap_content"/>\n   <TextView android:id="@+id/currentUrl" android:text="Belum ada URL" android:textColor="@color/text" android:textSize="11sp" android:ellipsize="end" android:maxLines="2" android:layout_marginTop="7dp" android:layout_width="match_parent" android:layout_height="wrap_content"/>\n   <TextView android:id="@+id/status" android:text="Status: siap" android:textColor="@color/accent" android:layout_marginTop="5dp" android:layout_width="match_parent" android:layout_height="wrap_content"/>\n   <WebView android:id="@+id/webView" android:layout_width="match_parent" android:layout_height="720dp" android:layout_marginTop="10dp" android:background="#FFFFFF" android:scrollbars="vertical|horizontal" android:overScrollMode="always"/>\n   <TextView android:text="Geser/scroll dan sentuh halaman langsung di dalam WebView." android:textColor="@color/muted" android:textSize="10sp" android:layout_marginTop="6dp" android:layout_width="match_parent" android:layout_height="wrap_content"/>\n   <Button android:id="@+id/randomUrl" android:text="RANDOM URL" android:textColor="@color/text" android:background="@drawable/button_dark" android:layout_marginTop="8dp" android:layout_width="match_parent" android:layout_height="48dp"/>\n  </LinearLayout>\n\n  <LinearLayout android:orientation="vertical" android:background="@drawable/panel" android:padding="14dp" android:layout_marginTop="12dp" android:layout_marginBottom="16dp" android:layout_width="match_parent" android:layout_height="wrap_content">\n   <LinearLayout android:orientation="horizontal" android:layout_width="match_parent" android:layout_height="wrap_content">\n    <TextView android:text="ACTIVITY LOG" android:textColor="@color/muted" android:textSize="11sp" android:letterSpacing="0.12" android:layout_weight="1" android:layout_width="0dp" android:layout_height="wrap_content"/>\n    <Button android:id="@+id/showLog" android:text="REFRESH" android:textColor="@color/text" android:background="@drawable/button_dark" android:layout_width="100dp" android:layout_height="40dp"/>\n   </LinearLayout>\n   <TextView android:id="@+id/logView" android:text="Belum ada log." android:textColor="@color/muted" android:textIsSelectable="true" android:fontFamily="monospace" android:textSize="11sp" android:layout_marginTop="8dp" android:layout_width="match_parent" android:layout_height="wrap_content"/>\n  </LinearLayout>\n </LinearLayout>\n</ScrollView>\n''')

